#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    long long countGoodSubarrays(vector<int>& a){
        int n=a.size();vector<int>L(n),R(n),st;
        for(int i=0;i<n;i++){
            while(!st.empty()&&a[st.back()]<=a[i])st.pop_back();
            L[i]=st.empty()?0:st.back()+1;st.push_back(i);
        }
        st.clear();for(int i=n-1;i>=0;i--){
            while(!st.empty()&&a[st.back()]<a[i])st.pop_back();
            R[i]=st.empty()?n-1:st.back()-1;st.push_back(i);
        }
        vector<array<int,31>> prv(n),nxt(n);
        array<int,31> last;last.fill(-1);
        for(int i=0;i<n;i++){
            prv[i]=last;for(int b=0;b<31;b++)if(a[i]&(1<<b))last[b]=i;
        }
        last.fill(n);
        for(int i=n-1;i>=0;i--){
            nxt[i]=last;for(int b=0;b<31;b++)if(a[i]&(1<<b))last[b]=i;
        }
        long long ans=0;
        for(int i=0;i<n;i++){
            int l=L[i],r=R[i];
            for(int b=0;b<31;b++)if(!(a[i]&(1<<b))){
                l=max(l,prv[i][b]+1);r=min(r,nxt[i][b]-1);
            }
            ans+=1LL*(i-l+1)*(r-i+1);
        }
        return ans;
    }
};
